<template>
 <section class="container py-4 management-page roles-page">
  <header class="management-heading"><h1>{{ tr('Roles y permisos','Roles and permissions') }}</h1><p>{{ tr('Elige una iglesia y configura el acceso de cada rol a los módulos.','Choose a church and configure each role’s module access.') }}</p></header>
  <label class="church-picker">{{ tr('Iglesia','Church') }}<select v-model="churchId" class="form-select" :disabled="busy"><option value="">{{ tr('Seleccionar iglesia','Select church') }}</option><option v-for="church in churches" :key="church.id" :value="church.id">{{ church.name }}</option></select></label>
  <p v-if="error" class="alert alert-danger" role="alert">{{ error }}</p><p v-if="notice" class="alert alert-success" role="status">{{ notice }}</p>
  <p v-if="loading" role="status">{{ tr('Cargando…','Loading…') }}</p>
  <template v-if="churchId && !loading">
   <p class="access-explanation">{{ tr('Solo lectura permite consultar y exportar. Editar habilita las acciones seleccionadas debajo de cada módulo. Las reglas de fechas, estados y límites de la iglesia siempre se mantienen. No concede privilegios de superadmin. Los roles nuevos comienzan sin acceso.','Read only allows viewing and exporting. Edit enables the actions selected below each module. Date, status and church boundaries always remain enforced. It does not grant superadmin privileges. New roles start with no access.') }}</p>
   <div class="roles-layout"><aside class="management-surface role-list"><h2>{{ tr('Roles existentes','Existing roles') }}</h2><button v-for="role in roles" :key="role.id" class="role-option" :class="{active:selectedId===role.id}" :disabled="busy" @click="selectRole(role)"><strong>{{ role.name }}</strong><span>{{ baseLabel(role.base_role) }} · {{ role.users_count }} {{ tr('usuarios','users') }}</span></button></aside>
   <section v-if="draft" class="management-surface role-editor"><h2>{{ tr('Acceso por módulo','Module access') }}</h2><label>{{ tr('Nombre del rol','Role name') }}<input v-model="draft.name" class="form-control" maxlength="100" :disabled="busy" /></label><p>{{ tr('Valores predeterminados de','Default preset') }}: <strong>{{ baseLabel(draft.base_role) }}</strong></p><div v-for="(module,key) in modules" :key="key" class="permission-row"><label :for="`permission-${key}`">{{ ui.locale==='es'?module.es:module.en }}</label><select :id="`permission-${key}`" v-model="draft.permissions[key]" class="form-select" :disabled="busy"><option value="none">{{ tr('Sin acceso','No access') }}</option><option value="read">{{ tr('Solo lectura','Read only') }}</option><option value="edit">{{ tr('Editar','Edit') }}</option></select><div class="capability-options" v-if="draft.permissions[key] !== 'none'"><label v-for="(cap,action) in capabilitiesFor(key)" :key="action"><span>{{ ui.locale==='es'?cap.es:cap.en }}</span><select class="form-select" :value="draft.capabilities[action] === undefined ? 'default' : String(draft.capabilities[action])" :disabled="busy || draft.permissions[key] !== 'edit'" @change="setCapability(action,$event.target.value)"><option value="default">{{ tr('Predeterminado','Default') }} · {{ draft.default_capabilities[action] ? tr('Permitido','Allowed') : tr('No permitido','Not allowed') }}</option><option value="true">{{ tr('Permitir','Allow') }}</option><option value="false">{{ tr('No permitir','Deny') }}</option></select></label><small v-if="draft.permissions[key]==='read'">{{ tr('Las acciones quedan inactivas en solo lectura.','Actions are inactive in read-only mode.') }}</small></div></div><p class="small">{{ tr('Iglesias, limpieza de calendarios y este administrador de roles son herramientas de plataforma exclusivas del superadmin.','Churches, calendar cleanup and this role manager are platform tools reserved for superadmin.') }}</p><div class="d-flex gap-2"><button class="btn btn-primary" :disabled="busy" @click="save">{{ tr('Guardar permisos','Save permissions') }}</button><button class="btn btn-outline-secondary" :disabled="busy" @click="selectRole(roles.find(r=>r.id===selectedId))">{{ tr('Descartar cambios','Discard changes') }}</button><button class="btn btn-outline-secondary" :disabled="busy" @click="restoreDefaults">{{ tr('Restablecer valores predeterminados','Restore defaults') }}</button></div></section></div>
   <FormSection :busy="busy" class="management-surface role-create" :title="tr('Crear rol','Create role')"><form @submit.prevent="create"><fieldset :disabled="busy"><label>{{ tr('Nombre','Name') }}<input v-model="newRole.name" class="form-control" maxlength="100" required /></label><label>{{ tr('Usar reglas de','Use workflow of') }}<select v-model="newRole.base_role" class="form-select"><option v-for="base in bases" :key="base" :value="base">{{ baseLabel(base) }}</option></select></label><button class="btn btn-primary">{{ tr('Crear rol sin acceso','Create role with no access') }}</button></fieldset></form></FormSection>
   <section class="management-surface role-assign"><h2>{{ tr('Asignar roles a usuarios','Assign roles to users') }}</h2><p>{{ tr('Los roles de departamento necesitan un departamento de esta iglesia. Las asignaciones se guardan por usuario.','Department roles require a department in this church. Assignments are saved per user.') }}</p><article v-for="user in users" :key="user.id" class="assignment"><div><strong>{{ user.name }}</strong><small>{{ user.email }}</small></div><label>{{ tr('Rol','Role') }}<select v-model="user.selected_role" class="form-select" :disabled="busy"><option v-for="role in roles" :key="role.id" :value="role.id">{{ role.name }}</option></select></label><label v-if="isDepartmentRole(user.selected_role)">{{ tr('Departamento','Department') }}<select v-model="user.department_id" class="form-select" :disabled="busy"><option :value="null">{{ tr('Seleccionar','Select') }}</option><option v-for="department in departments" :key="department.id" :value="department.id">{{ department.name }}</option></select></label><button class="btn btn-outline-primary" :disabled="busy" @click="assign(user)">{{ tr('Guardar asignación','Save assignment') }}</button></article><p v-if="!users.length">{{ tr('Crea usuarios en el módulo Usuarios y asígnales un rol aquí.','Create users in the Users module and assign a role here.') }}</p></section>
  </template>
 </section>
</template>
<script setup>
import FormSection from "../FormSection.vue"
import {ref,watch,onMounted} from 'vue'
import {useUiStore} from '../../stores/uiStore'
import {useAuthStore} from '../../stores/authStore'
import {superAdminApi} from '../../services/superAdminApi'
import {accessApi} from '../../services/accessApi'
import '../../styles/clerk-management.css'
const ui=useUiStore(),auth=useAuthStore(),tr=(es,en)=>ui.locale==='es'?es:en
const churches=ref([]),churchId=ref(''),roles=ref([]),modules=ref({}),capabilityCatalog=ref({}),users=ref([]),departments=ref([]),selectedId=ref(null),draft=ref(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const bases=['secretary','pastor','admin','member'],newRole=ref({name:'',base_role:'member'})
const baseLabel=base=>({secretary:tr('Secretaría','Clerk'),pastor:'Pastor',admin:tr('Administrador de departamento','Department administrator'),member:tr('Miembro de departamento','Department member')})[base]
const message=e=>Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||tr('No se pudo guardar.','Unable to save.')
const isDepartmentRole=id=>['admin','member'].includes(roles.value.find(r=>r.id===id)?.base_role)
function selectRole(role){notice.value='';if(!role){draft.value=null;return}selectedId.value=role.id;draft.value={...role,permissions:{...role.effective_permissions},capabilities:{...(role.capabilities || {})}}}
let generation=0
async function load(){const current=++generation;roles.value=[];users.value=[];draft.value=null;error.value='';if(!churchId.value)return;loading.value=true;try{const [data,depts]=await Promise.all([accessApi.list(churchId.value),superAdminApi.listDepartments(churchId.value)]);if(current!==generation)return;roles.value=data.roles;modules.value=data.modules;capabilityCatalog.value=data.capability_catalog;departments.value=depts;users.value=data.users.map(u=>({...u,selected_role:u.church_role_id||data.roles.find(r=>r.is_builtin&&r.base_role===u.role)?.id}));selectRole(roles.value.find(r=>r.id===selectedId.value)||roles.value[0])}catch(e){if(current===generation)error.value=message(e)}finally{if(current===generation)loading.value=false}}
watch(churchId,()=>{selectedId.value=null;notice.value='';load()})
async function run(action,success){busy.value=true;error.value='';notice.value='';try{await action();await load();await auth.refreshAccess();notice.value=success}catch(e){error.value=message(e)}finally{busy.value=false}}
async function save(){const data={revision:draft.value.revision,name:draft.value.name,permissions:draft.value.permissions,capabilities:draft.value.capabilities,reset_defaults:!!draft.value.reset_defaults && JSON.stringify(draft.value.permissions)===JSON.stringify(draft.value.default_permissions) && Object.keys(draft.value.capabilities).length===0};await run(()=>accessApi.update(churchId.value,selectedId.value,data),tr('Permisos guardados. Se aplican a todos los usuarios de este rol.','Permissions saved. They apply to every user with this role.'))}
function setCapability(action,value){if(value==='default')delete draft.value.capabilities[action];else draft.value.capabilities[action]=value==='true'}
const capabilitiesFor=module=>Object.fromEntries(Object.entries(capabilityCatalog.value).filter(([,cap])=>cap.module===module))
function restoreDefaults(){draft.value.permissions={...draft.value.default_permissions};draft.value.capabilities={};draft.value.reset_defaults=true;notice.value=tr('Valores predeterminados preparados. Guarda para aplicarlos solamente a este rol de esta iglesia.','Defaults restored in the editor. Save to apply them only to this role in this church.')}
async function create(){await run(async()=>{const role=await accessApi.create(churchId.value,newRole.value);selectedId.value=role.id;newRole.value={name:'',base_role:'member'}},tr('Rol creado. Configura sus permisos.','Role created. Configure its permissions.'))}
async function assign(user){await run(()=>accessApi.assign(churchId.value,user.id,{church_role_id:user.selected_role,department_id:user.department_id}),tr('Rol asignado.','Role assigned.'))}
onMounted(async()=>{try{let page=1,result;do{result=await superAdminApi.listChurches({page:page++});churches.value.push(...result.data)}while(result.next_page_url)}catch(e){error.value=message(e)}})
</script>
<style scoped>
.capability-options{grid-column:1/-1;display:grid;gap:10px;padding:8px 12px;background:#f4f7f5;border-radius:6px}.capability-options label{display:flex!important;flex-wrap:wrap;align-items:center;gap:10px}.capability-options select{max-width:210px}.capability-options label>span{flex:1}.capability-options input{width:16px;height:16px;flex:none}.roles-page{min-width:0}.church-picker{max-width:520px;display:block;margin-bottom:20px}.access-explanation{padding:16px;background:#eef5f0;color:#345440;border-radius:8px}.roles-layout{display:grid;grid-template-columns:minmax(210px,1fr) minmax(0,3fr);gap:20px}.role-list,.role-editor,.role-create,.role-assign{padding:20px;margin-bottom:20px;min-width:0}.roles-page h2{font-size:17px}.roles-page label{display:block;font-size:13px}.role-option{display:grid;gap:4px;width:100%;text-align:left;color:#284735;background:#f7f9f7;border:1px solid #d5dfd8;padding:12px;margin:8px 0}.role-option.active{background:#dfefe5;border-color:#2d7956}.role-option span{font-size:12px}.permission-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(130px,1fr);align-items:center;gap:14px;padding:10px 0;border-bottom:1px solid #e4eae6}.roles-page .btn{width:auto}.roles-page .btn-primary{color:#fff;background:#1f6f5c;border-color:#1f6f5c}.roles-page .btn-outline-secondary,.roles-page .btn-outline-primary{color:#28543d;background:#fff;border-color:#8da998}.roles-page .form-control,.roles-page .form-select{font-size:13px}.role-create fieldset{display:grid;gap:12px;margin-top:16px}.assignment{display:flex;flex-wrap:wrap;gap:14px;align-items:end;border-top:1px solid #dce5df;padding:16px 0}.assignment>div{flex:1;min-width:160px;overflow-wrap:anywhere}.assignment small{display:block}.assignment label{flex:1;min-width:160px}.roles-page p{font-size:13px}.role-editor>label{margin-bottom:12px}.role-editor>.small{margin-top:14px}@media(max-width:700px){.roles-layout{grid-template-columns:1fr}.role-list,.role-editor,.role-create,.role-assign{padding:14px}.assignment{display:grid;grid-template-columns:minmax(0,1fr)}}
</style>
